// Requires pdf-lib (already installed and allowed in your image)
const { PDFDocument } = require('pdf-lib');

const inputItems = await $input.all();
const outputs = [];

for (const item of inputItems) {
  if (!item.binary || Object.keys(item.binary).length === 0) {
    throw new Error('No binary data found. Pass a PDF as binary into this node.');
  }

  const binKey = Object.keys(item.binary)[0];
  const bin = item.binary[binKey];

  const mime = bin.mimeType || 'application/pdf';
  if (mime !== 'application/pdf') {
    throw new Error('Input binary is not a PDF (mimeType=' + mime + ').');
  }

  const originalName = bin.fileName || 'document.pdf';
  const base = originalName.replace(/\.pdf$/i, '');

  const srcBytes = Buffer.from(bin.data, 'base64');
  const srcPdf = await PDFDocument.load(srcBytes);
  const pageCount = srcPdf.getPageCount();

  for (let i = 0; i < pageCount; i++) {
    const newPdf = await PDFDocument.create();
    const [page] = await newPdf.copyPages(srcPdf, [i]);
    newPdf.addPage(page);

    const outBytes = await newPdf.save();
    const outB64 = Buffer.from(outBytes).toString('base64');
    const pageNum = i + 1;
    const pageName = `${base}_p${String(pageNum).padStart(3, '0')}.pdf`;

    outputs.push({
      json: {
        pageNumber: pageNum,
        totalPages: pageCount,
        originalFileName: originalName,
        pageFileName: pageName,
      },
      binary: {
        data: {
          data: outB64,
          mimeType: 'application/pdf',
          fileName: pageName,
          fileExtension: 'pdf',
        },
      },
    });
  }
}

return outputs;

parameters.description:
Searches the Qdrant vector database for Riyadh/Climate Corridor documents.

### CRITICAL: search_filter Syntax
You must return a VALID JSON object.

1. NO FILTER (Semantic Search only):
   {}

2. SINGLE Condition:
   { "key": "metadata.category", "match": { "value": "vegetation_greening" } }

3. MULTIPLE Conditions (AND logic) - Use 'must':
   {
     "must": [
       { "key": "metadata.category", "match": { "value": "vegetation_greening" } },
       { "key": "metadata.geographic_scope", "match": { "value": "city_riyadh" } }
     ]
   }

4. OR Logic - Use 'should':
   {
     "should": [
       { "key": "metadata.source_type", "match": { "value": "policy_document" } },
       { "key": "metadata.source_type", "match": { "value": "design_guideline" } }
     ]
   }

### Available Metadata Keys:
metadata.category, metadata.source_type, metadata.planning_phase, metadata.tags, metadata.geographic_scope, metadata.has_quantitative_data, metadata.design_elements, 

### Enum Values:
- categories: climate_microclimate, vegetation_greening, pedestrian_mobility, public_space, transit_infrastructure, water_irrigation, materials_surfaces
- source_type: policy_document, design_guideline, research_paper, case_study, species_database

Use 'relevant_keys' to limit output (e.g. "summary,url,tags").

